alter table public.farmanexo_verifications alter column created_by drop not null, alter column author_email drop not null;
alter table public.farmanexo_verifications add column guest_id uuid not null default gen_random_uuid();
drop policy verifications_read_team on public.farmanexo_verifications;
drop policy verifications_add_team on public.farmanexo_verifications;
create policy verifications_public_read on public.farmanexo_verifications for select to anon,authenticated using(true);
create policy verifications_public_add on public.farmanexo_verifications for insert to anon,authenticated with check (created_by is not distinct from (select auth.uid()) and author_email is not distinct from lower((select auth.jwt())->>'email'));
revoke all on public.farmanexo_verifications from anon,authenticated;
grant select(id,branch_id,medication_id,quantity,availability,commercial,channel,checked_at,verifier,notes,created_at,received_at,guest_id) on public.farmanexo_verifications to anon,authenticated;
grant insert(id,branch_id,medication_id,quantity,availability,commercial,channel,checked_at,verifier,notes,created_at,guest_id) on public.farmanexo_verifications to anon,authenticated;
drop policy medications_read_team on public.farmanexo_medications;
create policy medications_public_read on public.farmanexo_medications for select to anon,authenticated using(true);
revoke all on public.farmanexo_medications from anon,authenticated;
grant select(id,collection,custom_data,received_at) on public.farmanexo_medications to anon,authenticated;
grant insert(id,collection,custom_data,created_by) on public.farmanexo_medications to authenticated;
drop policy settings_read_team on public.farmanexo_settings;
create policy settings_public_read on public.farmanexo_settings for select to anon,authenticated using(true);
revoke all on public.farmanexo_settings from anon,authenticated;
grant select(id,rules,revision,updated_at) on public.farmanexo_settings to anon,authenticated;
grant update(rules,revision,updated_by) on public.farmanexo_settings to authenticated;
